# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_terr_a import T,A
TE=T+[['拉丁 terrestris → 中古英语 terrestre／terrestrial','土地、大地的 → 地球的、陆地的']]
IT=T+[['拉丁 in- + terra → interrare','放进土里、埋葬'],['古法语 enterrer → 英语 inter','安葬、埋葬']]
DI=IT[:2]+[['法语 dés- + enterrer → désenterrer → 英语 disinter','解除埋葬状态 → 从土里或墓中取出']]
TF=T+[['现代英语 terra + form → terraform','地球 + 塑造 → 把另一星球环境改造成近似地球']]
WB=[
E('terrestrial','/təˈrestriəl/','地球的；陆地的、陆生的；地面传播的','站在地面上看世界：相对天空是地上的，相对水里是陆上的，相对别的星球是地球的。','拉丁 terrestris“土地的、大地的”，经中古英语相关形式并配合 -al 形成 terrestrial。',TE,'terrestrial animals 指陆生动物；terrestrial television 指通过地面发射系统传播的电视。天文学的 terrestrial planets 是类地岩石行星，不等于只说地球本身。要先看它在与水域、太空还是卫星传输作比较。','terrestrial life；terrestrial animals；terrestrial planets；terrestrial television。','aquatic 是水生的；terrestrial 可说陆生。extraterrestrial 是地球之外的，比较范围又扩大了一层。',('The lesson compared terrestrial and aquatic habitats.','这堂课比较了陆地与水生栖息环境。'),('The programme was broadcast on terrestrial television.','这个节目通过地面电视系统播出。'),sources=['https://www.etymonline.com/word/terrestrial']),
E('terrestrially','/təˈrestriəli/','在地球上、陆地上；通过地面系统','把 terrestrial 的角度变成方式：发生在地上，或依靠地面设施进行。','terrestrial + -ly。',A(TE,'英语 terrestrially','在地球、陆地上；以地面方式'),'terrestrially transmitted signals 是通过地面系统发送的信号；terrestrially based observations 是从地面进行的观测。单词本身不说明具体是哪一种仪器或传播技术。','terrestrially based；terrestrially transmitted。','terrestrial 是形容词，修饰事物；terrestrially 是副词，描述发生地点或实现方式。',('The signal was transmitted terrestrially rather than by satellite.','信号是通过地面系统而不是卫星传输的。'),('The study combines terrestrially based observations with satellite data.','研究结合了地面观测与卫星数据。'),sources=['https://en.wiktionary.org/wiki/terrestrially']),
E('subterranean','/ˌsʌbtəˈreɪniən/','地下的；隐蔽的、暗中存在的','从脚下的地面继续往下走，进入表面看不见的空间。','拉丁 sub-“在下” + terra“土地”形成 subterraneus，英语配合 -an 形成 subterranean。',T+[['拉丁 sub + terra → subterraneus','土地下面的'],['英语 subterranean','地下的 → 不在表面显露的']],'a subterranean passage 是地下通道；subterranean tension 可以比喻表面平静下暗藏的紧张。比喻用法说看不见、未公开，不一定真的在地底举行。','subterranean tunnels；a subterranean river；subterranean tensions。','underground 较日常，也可作名词或副词；subterranean 较书面，主要作形容词。',('The old castle has several subterranean passages.','那座古堡有几条地下通道。'),('The novel reveals the subterranean tensions within the family.','小说揭示了这个家庭内部暗藏的紧张关系。'),sources=['https://www.etymonline.com/word/subterranean']),
E('inter','英 /ɪnˈtɜː/；美 /ɪnˈtɜːr/','安葬；埋葬〔正式〕','把遗体安放进土里或墓中，回到大地。','拉丁 in-“在里” + terra“土”形成 interrare，经古法语 enterrer 进入英语；与 inter-“之间”不是同一个构词来源。',IT,'be interred in a cemetery 是安葬在某墓地，常见于正式说明和纪念文字。这个独立动词重音在后面，过去式 interred、现在分词 interring 要双写 r。','inter the remains；be interred in；interred beside。','inter 是安葬；intern 可指拘留或实习，末尾多一个 n，词源和用法都不同。',('She was interred in the village cemetery.','她被安葬在村里的墓地。'),('The inscription records where the poet’s remains were interred.','碑文记载了那位诗人的遗骨安葬在何处。'),sources=['https://www.etymonline.com/word/inter']),
E('interment','英 /ɪnˈtɜːmənt/；美 /ɪnˈtɜːrmənt/','安葬；埋葬','把“安放入土”这件事作为一个名词来称呼。','经古法语 enterrement 借入，来自 enterrer；现代可联系 inter + -ment。',IT[:2]+[['古法语 enterrer → enterrement → 英语 interment','安葬 → 安葬这一行为']],'the place of interment 是安葬地点；the date of interment 是安葬日期。它指埋葬本身，和追悼、告别等整套葬礼安排并不完全重合。','the place of interment；interment records；after interment。','internment 是拘禁、收容；interment 是安葬。记住 terra“土”，能减少少写或多写 n 的混淆。',('The records show the date and place of interment.','记录注明了安葬的日期与地点。'),('A short service was held before the interment.','安葬前举行了一个简短仪式。'),sources=['https://www.etymonline.com/word/interment']),
E('disinter','英 /ˌdɪsɪnˈtɜː/；美 /ˌdɪsɪnˈtɜːr/','掘出〔遗体、埋藏物〕；重新找出〔旧材料〕','把原来埋在土里、压在旧资料堆里的东西重新取出来。','法语 désenterrer“挖出”，来自否定、逆转作用的 dés- + enterrer；现代也可按 dis- + inter 理解。',DI,'disinter remains 是从墓中掘出遗骸；disinter forgotten letters 可以比喻从遗忘中重新找出信件。它强调原先藏着或埋着，而不是泛泛拿起一个地面上的东西。','disinter remains；disinter an old document。','inter 是埋入；disinter 是取出。unearth 范围更宽，也常用于发现旧闻或证据。',('The remains were disinterred before the cemetery was relocated.','墓地迁移前，遗骸被起掘出来。'),('The biographer disinterred several forgotten letters from the archive.','传记作者从档案里重新找出了几封被遗忘的信。'),sources=['https://www.etymonline.com/word/inter']),
E('disinterment','英 /ˌdɪsɪnˈtɜːmənt/；美 /ˌdɪsɪnˈtɜːrmənt/','起掘遗体；掘出；重新发现〔书面〕','把已经安葬或埋藏的东西再次取出的整个过程。','disinter + -ment，形成行为名词。',A(DI,'英语 disinterment','掘出这一行为或过程'),'在正式记录里多说从墓中起掘遗体；文学或评论中也可比喻重新翻出被遗忘的材料。它与 interment 方向相反，但二者都保留了“土”的来历。','the disinterment of remains；a disinterment record。','exhumation 常专指起掘遗体；disinterment 与之接近，也有较宽的比喻用法。',('The archive contains a detailed record of the disinterment.','档案中保存了那次起掘的详细记录。'),('The essay describes the disinterment of a forgotten literary debate.','文章描述了一场被遗忘的文学论争如何被重新翻出。'),sources=['https://en.wiktionary.org/wiki/disinterment']),
E('terraform','英 /ˈterəfɔːm/；美 /ˈterəfɔːrm/','使〔星球〕地球化；改造成近似地球的环境','不只是盖一间房，而是设想把一颗星球的大气、温度等条件改得更像地球。','拉丁 terra“地球、土地” + 英语 form“塑造”；词语由科幻写作推广，早期记录见 Jack Williamson 的作品。',TF,'terraform a planet 是把行星环境改造成更适合人类等地球生命居住的样子。这是科幻与行星环境研究中的设想名称；词义不保证某项方案已经实现，也不等于在原有环境里只建密封基地。','terraform a planet；attempt to terraform。','colonise 是建立定居地等；terraform 强调改造环境本身，二者不是同一个动作。',('The novel imagines engineers trying to terraform a distant planet.','小说设想工程师尝试把一颗遥远行星改造成近似地球的环境。'),('The game asks players to terraform a barren world.','这款游戏让玩家把一个荒芜世界改造成适合居住的环境。'),sources=['https://www.merriam-webster.com/dictionary/terraform','https://www.grc.nasa.gov/www/k-12/Aero2000/studweb/glossary/trrafrm.html']),
E('terraforming','英 /ˈterəfɔːmɪŋ/；美 /ˈterəfɔːrmɪŋ/','星球地球化；行星环境改造的设想或过程','把“让另一个世界更像地球”当作一项整体环境改造来讨论。','terraform + -ing，可指活动、过程，也可构成进行时。',A(TF,'英语 terraforming','对星球环境进行地球化改造的设想、过程'),'a terraforming project 是行星环境改造项目或构想。文章可能讨论大气、温度、水和生态等多方面条件，不能把 terraforming 缩成“往沙地上撒点种子”。','a terraforming proposal；the challenges of terraforming。','landscaping 通常是园林或局部地景整理；terraforming 的典型对象是另一星球的环境条件，尺度与目的不同。',('The documentary discusses the scientific challenges of terraforming.','纪录片讨论了星球环境改造面临的科学难题。'),('Terraforming is a central theme of the science fiction novel.','星球地球化是那本科幻小说的核心主题。'),sources=['https://www.grc.nasa.gov/www/k-12/Aero2000/studweb/glossary/trrafrm.html','https://www.merriam-webster.com/dictionary/terraform']),
E('terrigenous','/təˈrɪdʒənəs/','陆源的；来自陆地的〔地质〕','颗粒现在可能躺在海底，但它们的老家在陆地。','拉丁 terrigena“土地所生的”，由 terra 与表示出生、产生的词族组成；英语以 -ous 形容词形式表达。',T+[['拉丁 terra + gignere 相关成分 → terrigena','土地 + 产生 → 生于土地'],['英语 terrigenous','由陆地来源产生的，尤其指陆源沉积物']],'terrigenous sediment 常是陆地岩石风化、侵蚀后，经过河流、风等搬运形成的沉积物。关注来源而非最后落脚点，所以海底也可以有陆源沉积物。','terrigenous sediment；terrigenous material；terrigenous input。','terrestrial 常说在陆地上或属于地球；terrigenous 更突出来自陆地的来源关系。',('The sample contains a large amount of terrigenous sediment.','样品里含有大量陆源沉积物。'),('The river carries terrigenous material towards the coast.','河流把陆源物质运向海岸。'),sources=['https://www.merriam-webster.com/dictionary/terrigenous']),
E('terrene','/təˈriːn/','大地的；尘世的；土地〔文学、旧式〕','把目光从天上拉回地面，谈脚下土地和人间生活。','经盎格鲁法语 terreine／terrin 及拉丁 terrenus，接 terra“土地”。',T+[['拉丁 terrenus → 法语 terreine／terrin → 英语 terrene','土地的 → 大地的、尘世的'],['英语名词 terrene','大地、地面']],'terrene concerns 可以说世俗生活中的事务，与天界、精神世界形成对照。名词用法也可表示土地或地面；如今比较文学化，日常用 earthly、worldly 或 terrain 更直接。','terrene concerns；the celestial and the terrene。','terrain 是常用的地形名词；terrene 常作文学形容词。两词最终都接土地，但发音末尾分别偏 /reɪn/ 与 /riːn/。',('The poem contrasts celestial beauty with terrene suffering.','诗歌把天界之美与人间苦难相对照。'),('The writer turns from abstract ideals to terrene concerns.','作者从抽象理想转向了尘世事务。'),sources=['https://www.merriam-webster.com/dictionary/terrene']),
E('terrier','英 /ˈteriə/；美 /ˈteriər/','㹴犬；旧式土地清册','这种犬的名字与钻洞追逐猎物有关：它是一种与泥土、洞穴打交道的狗。','古法语 chien terrier“地洞猎犬”缩短为 terrier；terrier 接中古拉丁 terrarius“土地的”，来自 terra。',T+[['中古拉丁 terrarius → 古法语 chien terrier','土地的 → 钻地洞追猎的犬'],['英语 terrier','㹴犬；另有同源土地清册名词支线']],'日常首先指㹴犬类；某些比喻里也可形容追着问题不放的人。旧档案里的 terrier 可能是土地登记清册，名称直接关乎土地，不是在记一只狗的履历。','a small terrier；a terrier breed；a land terrier。','terrier 的犬名来自历史用途，不代表每只这种犬都在猎捕。罕见的钻孔工具同形词另有来源，不按 terra 分析。',('The little terrier waited beside the gate.','那只小㹴犬守在门边。'),('The archivist found a terrier listing the estate’s fields.','档案员找到了一份列明庄园田地的土地清册。'),sources=['https://www.etymonline.com/word/terrier','https://en.wiktionary.org/wiki/terrier']),
E('terrazzo','英 /təˈrætsəʊ/；美 /təˈrɑːtsoʊ/','水磨石；碎石骨料磨光材料','许多小碎石被黏在一起，再磨成一张平滑的彩色表面。','借自意大利 terrazzo，原指露台、平台，与 terrace 同属土地、台地词族。',T+[['意大利 terrazzo','平台、露台'],['英语 terrazzo','用于地面等的碎石骨料复合材料']],'terrazzo 常由大理石等碎料配合水泥或树脂结合料制成，再磨光。你看到的斑点通常是嵌在里面的颗粒，不是整块天然大理石自身的纹路；也可以用于墙面、台面等。','a terrazzo floor；terrazzo tiles；a terrazzo surface。','terracotta 是烧制陶土；terrazzo 是碎料与结合料形成的复合材料，名字都带 terra，却不是同一种东西。',('The entrance hall has a polished terrazzo floor.','门厅铺着磨光的水磨石地面。'),('Small coloured chips give the terrazzo its speckled appearance.','细小的彩色碎料让水磨石呈现斑点外观。'),sources=['https://www.etymonline.com/word/terrazzo','https://ntma.com/why-terrazzo/faqs/']),
E('terra','英 /ˈterə/；美 /ˈterə/','土地、大地〔借用词〕；行星地貌名称中的广大陆块','直接把拉丁语的“土地”搬进英语，常留在专门名称里。','直接借自拉丁 terra“土地、地面、大地”。',T+[['拉丁 terra → 英语 terra','土地、大地；在地貌命名等领域保留拉丁形式']],'普通聊天一般用 land 或 earth。terra 常见于借用表达和行星地貌名称；天体命名中的 terra 表示广大陆块，复数 terrae，不代表那里的岩石一定像地球一样。','terra in a place name；the plural terrae。','terra 是“土地”这一拉丁来源形式；terrain 是经法语发展的常用地形词。大写 Terra 还可作为地球或名称使用，要看语境。',('The guide explains the meaning of terra in planetary place names.','指南解释了 terra 在行星地貌名称中的含义。'),('The atlas uses terrae as the plural of terra.','这本地图集用 terrae 作 terra 的复数。'),sources=['https://planetarynames.wr.usgs.gov/DescriptorTerms','https://en.wiktionary.org/wiki/terra']),
]
